#!/bin/bash
# Two Kinds of Dollar: gen_vhost.sh writes an nginx vhost and a health check
# script with heredocs. Each file mixes values to fill in now (DOMAIN, PORT)
# with $ that must stay literal (nginx variables, the generated script's own
# $1). The draft quotes the wrong heredoc and leaves the other unquoted.
SANDBOX="$1"
cd "$SANDBOX" || exit 1
mkdir -p examples sites

cat > examples/shop.example.com.conf <<'CONF'
# generated by gen_vhost.sh - do not edit by hand
server {
    listen 80;
    server_name shop.example.com;

    access_log /var/log/nginx/shop.example.com.access.log;

    location / {
        proxy_pass http://127.0.0.1:8081;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    location ~ /\.(git|env) {
        deny all;
    }
}
CONF

cat > examples/shop.example.com-healthcheck.sh <<'HC'
#!/bin/bash
# healthcheck for shop.example.com (generated by gen_vhost.sh)
# usage: shop.example.com-healthcheck.sh [PATH]      default PATH: /healthz
path="${1:-/healthz}"
url="http://127.0.0.1:8081$path"
if curl -fsS -o /dev/null -H "Host: shop.example.com" "$url"; then
  echo "OK $url"
else
  echo "FAIL $url" >&2
  exit 1
fi
HC
chmod +x examples/shop.example.com-healthcheck.sh

cat > gen_vhost.sh <<'SCRIPT'
#!/bin/bash
# gen_vhost.sh DOMAIN PORT
# Writes sites/DOMAIN.conf (nginx vhost) and sites/DOMAIN-healthcheck.sh.
# examples/ shows the exact output for: ./gen_vhost.sh shop.example.com 8081
domain=$1
port=$2
mkdir -p sites

cat > "sites/$domain.conf" <<EOF
# generated by gen_vhost.sh - do not edit by hand
server {
    listen 80;
    server_name $domain;

    access_log /var/log/nginx/$domain.access.log;

    location / {
        proxy_pass http://127.0.0.1:$port;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    location ~ /\.(git|env) {
        deny all;
    }
}
EOF

cat > "sites/$domain-healthcheck.sh" <<'EOF'
#!/bin/bash
# healthcheck for $domain (generated by gen_vhost.sh)
# usage: $domain-healthcheck.sh [PATH]      default PATH: /healthz
path="${1:-/healthz}"
url="http://127.0.0.1:$port$path"
if curl -fsS -o /dev/null -H "Host: $domain" "$url"; then
  echo "OK $url"
else
  echo "FAIL $url" >&2
  exit 1
fi
EOF
chmod +x "sites/$domain-healthcheck.sh"
echo "wrote sites/$domain.conf and sites/$domain-healthcheck.sh"
SCRIPT
chmod +x gen_vhost.sh
